package inventory

import "sort"

// ReorderAt 是补货阈值：Qty 低于它的条目需要补货。
const ReorderAt = 5

// Item 是库存里的一条记录。
type Item struct {
	SKU string
	Qty int
}

// Stock 返回某个 SKU 的数量；没有这个 SKU 时返回 0。
func Stock(items []Item, sku string) int {
	for _, it := range items {
		if it.SKU == sku {
			return it.Qty
		}
	}
	return 0
}

// Reorder 返回需要补货（Qty < ReorderAt）的条目，按 Qty 升序、同 Qty 按 SKU 升序。
// 它不修改传入的切片。
func Reorder(items []Item) []Item {
	low := make([]Item, 0, len(items))
	for _, it := range items {
		if it.Qty < ReorderAt {
			low = append(low, it)
		}
	}
	sort.Slice(low, func(i, j int) bool {
		if low[i].Qty != low[j].Qty {
			return low[i].Qty < low[j].Qty
		}
		return low[i].SKU < low[j].SKU
	})
	return low
}
