func LowStockLines(items []inventory.Item, unitCents map[string]int, discountPct int) []string {
	low := inventory.Reorder(items)
	lines := make([]string, 0, len(low))
	for _, it := range low {
		amount := pricing.BulkTotal(unitCents[it.SKU], it.Qty, discountPct)
		lines = append(lines, fmt.Sprintf("%s = %d", SKULine(it.SKU, it.Qty), amount))
	}
	return lines
}
